const SOHRAI_PAINTING_INFO={title:"Sohrai Painting",region:"Jharkhand",state:"Jharkhand, India",tradition:"Tribal wall and floor art",practitioners:"Women of the Kurmi, Santhal, Munda, and Oraon tribal communities",festival:"Sohrai (cattle harvest festival, November)",languages:["Sadri","Santali","Mundari","Kurukh","Hindi"],giStatus:"GI-tagged (2019)",summary:"Sohrai is a ceremonial wall and floor painting tradition practiced by the tribal women of Jharkhand during the Sohrai harvest festival in November. Named after the Sohrai sowing festival, the paintings celebrate cattle — the backbone of the agrarian tribal economy — and are drawn with natural earth pigments on the mud walls of village homes. The art form received a Geographical Indication (GI) tag in 2019."},HISTORICAL_BACKGROUND=[{heading:"Origins in the Forests of Chota Nagpur",body:"Sohrai painting traces its origins to the forested Chota Nagpur Plateau of eastern India, home to the Kurmi, Santhal, Munda, and Oraon tribal communities. The art is inextricably tied to the Sohrai festival, a cattle-harvest celebration held in late November after the paddy harvest. The word 'Sohrai' is believed to derive from the Paleolithic cave art tradition of the region — rock paintings in the nearby Isko caves bear striking visual similarity to modern Sohrai motifs."},{heading:"A Cattle Festival",body:"The Sohrai festival honours cattle — particularly the bull and the cow — which are the foundation of tribal agrarian life. On Sohrai day, cattle are bathed, anointed with oil and vermillion, and fed special rice. The walls of the cattle shed and the home are freshly plastered with mud and then painted with Sohrai motifs depicting cattle, elephants, peacocks, and the Tree of Life. The paintings are an offering of gratitude for the harvest and a prayer for continued fertility."},{heading:"A Women's Tradition",body:"Sohrai is exclusively practiced by women. Mothers pass the tradition to daughters through observation and practice — there is no formal training, no written manual, and no preparatory sketch. The women paint freehand, using fingers, chewed twigs, and cloth rags. The art is ephemeral: it is painted fresh each year on the mud walls, and the monsoon rains of the following summer wash it away, beginning the cycle again."},{heading:"Visual Roots in Prehistory",body:"Art historians have noted the striking visual continuity between Sohrai painting and the prehistoric rock art of the Chota Nagpur region. The rock paintings at Isko, Satpahar, and Thetangi — some dating back over 10,000 years — depict the same cattle, elephants, and hunting scenes that appear in modern Sohrai art. Sohrai painting is one of the few living folk-art traditions that retains a direct visual link to the Mesolithic and Chalcolithic rock art of India."},{heading:"Modern Recognition",body:"Sohrai painting was awarded a Geographical Indication (GI) tag in 2019, recognising it as a distinctive cultural product of Jharkhand. In recent years, the art form has been adapted onto paper and canvas by tribal women artists, allowing it to reach urban and international markets. Government initiatives and NGOs have supported training programs to ensure the tradition continues despite the increasing shift from mud-plaster to brick-and-cement homes in rural Jharkhand."}],NATURAL_PIGMENTS=[{name:"Pila Mitti (Yellow Earth)",color:"#d4a017",description:"Yellow ochre earth rich in limonite, collected from riverbeds and forest clearings. Provides the warm yellow used for cattle bodies, sun motifs, and the Tree of Life.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Red_ochre.jpg/200px-Red_ochre.jpg"},{name:"Lal Mitti (Red Earth)",color:"#a83d28",description:"Red hematite-rich clay used for outlines, borders, and ritual vermillion marks. Sourced from laterite soils common in the Chota Nagpur plateau.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Red_ochre.jpg/200px-Red_ochre.jpg"},{name:"Kaala Mitti (Black Earth)",color:"#2a1f1a",description:"Black manganese-rich earth or charred rice husk. Used for the dark outlines, decorative dots, and the silhouettes of cattle and elephants.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"},{name:"Safed Mitti (White Chalk)",color:"#f8f0e0",description:"White kaolin clay collected from white-soil patches in the forest. Provides the brilliant white used for highlights, dots, and the inner details of motifs.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"},{name:"Kala Paani (Charcoal Water)",color:"#3d3d3d",description:"A liquid black made by soaking burnt wood charcoal in water. Used for fine-line work and dotting, applied with a frayed twig.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"},{name:"Brown Soil (Dhusor Mitti)",color:"#8b5a2b",description:"A brownish earth used for filling larger background areas, particularly the cattle shed walls. Often mixed with the white chalk to create softer tones.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Chalk.jpg/200px-Chalk.jpg"}],TRADITIONAL_MOTIFS=[{name:"Cattle (Gai-Bail)",region:"Hazaribagh, Bokaro",occasion:"Sohrai festival",description:"The most central Sohrai motif — cows and bulls are painted as a tribute to the cattle that plough the fields and provide milk. The animals are drawn in profile with elaborate decorative patterns inside their bodies.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Sohrai_Cattle.jpg/440px-Sohrai_Cattle.jpg"},{name:"Elephant (Hathi)",region:"Ranchi, Lohardaga",occasion:"Sohrai, weddings",description:"Elephants are symbols of strength, royalty, and forest power. Drawn in rows along the lower wall, often with peacocks riding on their backs.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Sohrai_Elephant.jpg/440px-Sohrai_Elephant.jpg"},{name:"Peacock (Mor)",region:"Hazaribagh, Ramgarh",occasion:"Sohrai festival",description:"The peacock is a symbol of beauty and the monsoon. Sohrai peacocks are drawn with fanned tail-feathers filled with geometric dot-and-line patterns in white and yellow.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Sohrai_Peacock.jpg/440px-Sohrai_Peacock.jpg"},{name:"Tree of Life (Jhad)",region:"All Jharkhand",occasion:"Sohrai, harvest",description:"A stylised tree with symmetric branches, roots, and birds perched on top. Symbolises the interconnectedness of forest, cattle, and human life.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Sohrai_Tree.jpg/440px-Sohrai_Tree.jpg"},{name:"Flower (Phool)",region:"All Jharkhand",occasion:"Sohrai festival",description:"Stylised lotus and sunflower motifs drawn as borders or fillers between the larger animal figures. Symbol of fertility and the blooming of the harvest.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Sohrai_Flower.jpg/440px-Sohrai_Flower.jpg"},{name:"Sun (Surya)",region:"Hazaribagh",occasion:"Sohrai festival",description:"A radiating sun motif drawn at the top of the wall, symbolising the life-giving force that ripens the harvest. Often paired with the moon and stars.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Sohrai_Sun.jpg/440px-Sohrai_Sun.jpg"}],GALLERY_ITEMS=[{title:"Sohrai Wall in a Hazaribagh Home",region:"Hazaribagh, Jharkhand",year:"Contemporary (c. 2021)",description:"A freshly painted Sohrai wall depicting cattle, peacocks, and the Tree of Life. Painted for the Sohrai festival in November.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Sohrai_Diwali_Chowk.jpg/440px-Sohrai_Diwali_Chowk.jpg",category:"wall"},{title:"Cattle and Elephant Motifs",region:"Bokaro, Jharkhand",year:"Contemporary (c. 2020)",description:"A row of cattle and elephant motifs along the lower wall of a tribal home. The dot-and-line fill patterns are characteristic of Kurmi Sohrai.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Sohrai_Wall_Peacock.jpg/440px-Sohrai_Wall_Peacock.jpg",category:"wall"},{title:"Peacock and Lotus Border",region:"Ramgarh, Jharkhand",year:"Contemporary (c. 2022)",description:"A peacock and lotus border painted along the top edge of a wall, framing the cattle motifs below.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/Sohrai_Ganesha_Threshold.jpg/440px-Sohrai_Ganesha_Threshold.jpg",category:"wall"},{title:"Sohrai on Canvas (Modern Adaptation)",region:"Ranchi, Jharkhand",year:"Contemporary (c. 2023)",description:"A Sohrai painting on canvas, created by a tribal woman artist for the urban market. The motifs are traditional; the medium is modern.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Sohrai_Vivah_Wall.jpg/440px-Sohrai_Vivah_Wall.jpg",category:"canvas"},{title:"Tree of Life with Birds",region:"Lohardaga, Jharkhand",year:"Contemporary (c. 2021)",description:"A Tree of Life motif painted on the central wall of a Munda home, with stylised birds perched on the branches.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8e/Sohrai_Harvest.jpg/440px-Sohrai_Harvest.jpg",category:"wall"},{title:"Sun and Moon Composition",region:"Hazaribagh, Jharkhand",year:"Contemporary (c. 2022)",description:"A radiating sun and crescent moon drawn at the top of a wall, above a row of cattle motifs. Symbolises the cosmic order that governs the harvest cycle.",imageUrl:"https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Sohrai_Holi.jpg/440px-Sohrai_Holi.jpg",category:"wall"}],GALLERY_CATEGORIES=[{id:"all",label:"All"},{id:"wall",label:"Wall Paintings"},{id:"canvas",label:"Canvas Adaptations"}],REFERENCES_LIST=[{title:"Sohrai Painting — A Tribal Wall Art of Jharkhand",author:"Bulu Imam (Sanskriti, Hazaribagh)",publisher:"Tribal Women Artists' Collective",year:2012,url:"https://en.wikipedia.org/wiki/Sohrai"},{title:"The Painted Walls of Hazaribagh",author:"Imam, Bulu",publisher:"Prakash Books",year:1998,url:"https://en.wikipedia.org/wiki/Sohrai_painting"},{title:"Sohrai and Khovar Paintings — GI Tag Documentation",author:"Government of Jharkhand",publisher:"Department of Industries",year:2019,url:"https://www.jharkhand.gov.in/"},{title:"Tribal Art of India: Sohrai Painting",author:"CCRT (Centre for Cultural Resources and Training)",publisher:"Ministry of Culture, Government of India",year:2020,url:"https://ccrtindia.gov.in/"},{title:"Wikipedia: Sohrai painting",author:"Wikipedia contributors",publisher:"Wikipedia",year:2024,url:"https://en.wikipedia.org/wiki/Sohrai_painting"},{title:"Prehistoric Rock Art of Chota Nagpur",author:"Mathpal, Yadav",publisher:"Agam Kala Prakashan",year:2008,url:"https://en.wikipedia.org/wiki/Isko_caves"}];"undefined"!=typeof window&&(window.SOHRAI_DATA={info:SOHRAI_PAINTING_INFO,history:HISTORICAL_BACKGROUND,pigments:NATURAL_PIGMENTS,motifs:TRADITIONAL_MOTIFS,gallery:GALLERY_ITEMS,galleryCategories:GALLERY_CATEGORIES,references:REFERENCES_LIST}),"undefined"!=typeof module&&module.exports&&(module.exports={SOHRAI_PAINTING_INFO:SOHRAI_PAINTING_INFO,HISTORICAL_BACKGROUND:HISTORICAL_BACKGROUND,NATURAL_PIGMENTS:NATURAL_PIGMENTS,TRADITIONAL_MOTIFS:TRADITIONAL_MOTIFS,GALLERY_ITEMS:GALLERY_ITEMS,GALLERY_CATEGORIES:GALLERY_CATEGORIES,REFERENCES_LIST:REFERENCES_LIST});